package top.monitorglobal.tv;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w1280dp-h720dp-land-hdpi",instrumentedPackages={"top.monitorglobal.tv"}) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class WeatherSatelliteTest {
 Context c;long now;private Object field(Object o,String key)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(o);}
 @Before public void setup(){c=RuntimeEnvironment.getApplication();now=org.robolectric.shadows.ShadowSystem.currentTimeMillis();org.robolectric.shadows.ShadowSettings.setCanDrawOverlays(true);Shadows.shadowOf((PowerManager)c.getSystemService(Context.POWER_SERVICE)).setIsInteractive(true);}
 byte[] png(int w,int h,boolean empty){Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);if(!empty)b.eraseColor(0xff778899);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
 String xml(long end){return "<Domains><Domain>"+InfraredPlan.iso(end-5*InfraredPlan.STEP)+"/"+InfraredPlan.iso(end)+"/PT10M</Domain></Domains>";}
 byte[] partial(){Bitmap b=Bitmap.createBitmap(512,InfraredPlan.SOUTHEAST.height,Bitmap.Config.ARGB_8888);b.eraseColor(0xff778899);Paint p=new Paint();p.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.CLEAR));new Canvas(b).drawRect(0,0,256,b.getHeight(),p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
 WeatherSatelliteClient.Frame example(){return new WeatherSatelliteClient.Frame(Bitmap.createBitmap(512,InfraredPlan.SOUTHEAST.height,Bitmap.Config.ARGB_8888),null,now-1800000,InfraredPlan.SOUTHEAST,Arrays.asList(now-1800000));}
 @Test public void partialOrEmptyFramesAreSkippedAndCacheIsBoundedAndReleased()throws Exception{long last=now/600000*600000-1200000;AtomicInteger images=new AtomicInteger();byte[] full=png(512,InfraredPlan.SOUTHEAST.height,false),empty=png(512,InfraredPlan.SOUTHEAST.height,true),legend=png(420,95,false),partial=partial();WeatherSatelliteClient client=new WeatherSatelliteClient(c,(url,limit,deadline)->{if(url.contains("DescribeDomains"))return xml(last).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(url.equals(InfraredPlan.LEGEND))return legend;images.incrementAndGet();return url.contains("TIME="+InfraredPlan.iso(last))?empty:url.contains("TIME="+InfraredPlan.iso(last-600000))?partial:full;});
  try{WeatherSatelliteClient.Frame frame=client.latest(InfraredPlan.SOUTHEAST,now);assertNotNull(frame);assertEquals(last-1200000,frame.at);assertFalse(frame.times.contains(last));assertFalse(frame.times.contains(last-600000));assertEquals(0xff102d40,frame.image.getPixel(510,frame.image.getHeight()-1));assertTrue(frame.image.getPixel(100,100)!=0);frame.close();int count=images.get();frame=client.latest(InfraredPlan.SOUTHEAST,now);assertNotNull(frame);assertEquals(count,images.get());frame.close();assertTrue(client.cacheBytes()<=4194304);}finally{client.close();}assertEquals(0,client.cacheBytes());assertNull(client.frame(InfraredPlan.SOUTHEAST,last,now));}
 @Test public void sequenceWaitsForWeatherAndCancellationPreventsLateWindow()throws Exception{AtomicBoolean allowed=new AtomicBoolean(true);WeatherSatelliteSequence sequence=new WeatherSatelliteSequence(c,allowed::get,()->new WeatherSatelliteSequence.Loader(){public WeatherSatelliteClient.Frame load(){return example();}public void close(){}});try{sequence.start();for(int i=0;i<200&&field(sequence,"frame")==null;i++){Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertNotNull(field(sequence,"frame"));assertNull(field(sequence,"current"));Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(12999));assertNull(field(sequence,"current"));Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(1));assertNotNull(field(sequence,"current"));WindowManager.LayoutParams p=(WindowManager.LayoutParams)((View)field(sequence,"current")).getLayoutParams();assertTrue((p.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE)!=0);sequence.cancel();assertFalse(sequence.pending());assertNull(field(sequence,"current"));Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(40));assertNull(field(sequence,"current"));}finally{sequence.close();}}
 @Test public void lossOfPriorityAndLateNetworkCompletionCannotCoverAnAlert()throws Exception{AtomicBoolean allowed=new AtomicBoolean(false);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);WeatherSatelliteClient.Frame old=example();WeatherSatelliteSequence sequence=new WeatherSatelliteSequence(c,allowed::get,()->new WeatherSatelliteSequence.Loader(){public WeatherSatelliteClient.Frame load()throws Exception{entered.countDown();release.await(3,TimeUnit.SECONDS);return old;}public void close(){release.countDown();}});sequence.start();assertTrue(entered.await(3,TimeUnit.SECONDS));sequence.cancel();for(int i=0;i<100&&!old.image.isRecycled();i++){Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(old.image.isRecycled());Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(35));assertNull(field(sequence,"current"));sequence.close();}
 @Test public void remoteViewerPausesPlaybackAndReleasesItsFrameOnStop()throws Exception{
  AtomicBoolean readerClosed=new AtomicBoolean();long end=now/600000*600000-1200000;
  org.robolectric.android.controller.ActivityController<WeatherSatelliteActivity> controller=Robolectric.buildActivity(WeatherSatelliteActivity.class);WeatherSatelliteActivity activity=controller.get();
  activity.sourceFactory=context->new WeatherSatelliteClient(context,new WeatherSatelliteClient.Reader(){public byte[] read(String url,int limit,long deadline){if(url.contains("DescribeDomains"))return xml(end).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(url.equals(InfraredPlan.LEGEND))return png(420,95,false);int height=Integer.parseInt(android.net.Uri.parse(url).getQueryParameter("HEIGHT"));return png(512,height,false);}public void close(){readerClosed.set(true);}});
  controller.create().start().resume().visible();
  try{for(int i=0;i<400&&(Boolean)field(activity,"busy");i++){Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertFalse((Boolean)field(activity,"busy"));WeatherSatelliteClient.Frame displayed=(WeatherSatelliteClient.Frame)field(activity,"frame");assertNotNull(displayed);((android.widget.Button)field(activity,"animation")).performClick();assertTrue((Boolean)field(activity,"playing"));controller.pause().stop();assertFalse((Boolean)field(activity,"playing"));assertNull(field(activity,"frame"));assertTrue(displayed.image.isRecycled());assertTrue(readerClosed.get());Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(30));assertNull(field(activity,"frame"));}finally{controller.destroy();}
 }
 @Test public void cardRendersUsingProducerImageWhenSourceProbeIsAvailable()throws Exception{WeatherSatelliteClient.Frame frame=example();java.nio.file.Path file=Paths.get("/tmp/tv-satellite-real.png");if(Files.exists(file)){frame.close();long at=Long.parseLong(new String(Files.readAllBytes(Paths.get("/tmp/tv-satellite-time.txt")),java.nio.charset.StandardCharsets.UTF_8).trim());long sourceNow=Long.parseLong(new String(Files.readAllBytes(Paths.get("/tmp/tv-satellite-now.txt")),java.nio.charset.StandardCharsets.UTF_8).trim());org.robolectric.shadows.ShadowSystemClock.advanceBy(java.time.Duration.ofMillis(sourceNow-org.robolectric.shadows.ShadowSystem.currentTimeMillis()));WeatherSatelliteClient source=new WeatherSatelliteClient(c,(url,limit,deadline)->url.contains("DescribeDomains")?xml(at).getBytes(java.nio.charset.StandardCharsets.UTF_8):Files.readAllBytes(Paths.get(url.equals(InfraredPlan.LEGEND)?"/tmp/tv-satellite-legend.png":"/tmp/tv-satellite-real.png")));try{frame=source.latest(InfraredPlan.SOUTHEAST,sourceNow);assertNotNull(frame);}finally{source.close();}}WeatherSatelliteCard card=new WeatherSatelliteCard(c,frame,false);int width=630;card.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.AT_MOST));card.layout(0,0,width,card.getMeasuredHeight());assertTrue(card.getHeight()<950);Bitmap image=Bitmap.createBitmap(width,card.getHeight(),Bitmap.Config.ARGB_8888);card.draw(new Canvas(image));ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.JPEG,85,out);System.out.println("TV_SATELLITE_PREVIEW_BASE64 "+java.util.Base64.getEncoder().encodeToString(out.toByteArray()));image.recycle();card.clear();frame.close();}
}
